select ss.product_id, case when ss.revenue >= 3100 then 'high' when ss.revenue >= 800 then 'mid' else 'low' end as revenue_bucket, count(i.quantity) as quantity_count from inventory i inner join store_sales ss on i.store_id = ss.store_id and i.product_id = ss.product_id where ss.units <= 11 group by ss.product_id, case when ss.revenue >= 3100 then 'high' when ss.revenue >= 800 then 'mid' else 'low' end having count(i.quantity) >= 5;
